// DeploymentsPage.js
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import NewDeploymentForm from './NewDeploymentForm';
import DeploymentDetails from './DeploymentDetails';

const DeploymentsPage = () => {
  const [showForm, setShowForm] = useState(false);
  const [deploymentInfo, setDeploymentInfo] = useState(JSON.parse(localStorage.getItem('deploymentInfo')) || null);
  const navigate = useNavigate();

  useEffect(() => {
    const savedDeploymentInfo = JSON.parse(localStorage.getItem('deploymentInfo'));
    if (savedDeploymentInfo) {
      setDeploymentInfo(savedDeploymentInfo);
    }
  }, []);

  const handleNewDeploymentClick = () => {
    setShowForm(true);
  };

  return (
    <div>
      <h1>Deployments</h1>
      {!showForm && !deploymentInfo && (
        <button onClick={handleNewDeploymentClick}>New Deployment</button>
      )}
      {showForm && (
        <NewDeploymentForm
          setShowForm={setShowForm}
          setDeploymentInfo={(info) => {
            setDeploymentInfo(info);
            navigate('/deployments');
          }}
        />
      )}
      {!showForm && deploymentInfo && (
        <DeploymentDetails deploymentInfo={deploymentInfo} />
      )}
    </div>
  );
};

export default DeploymentsPage;
